        }
      } catch (e) {
        author = 'Unknown author';
      }

      let likes = '';
      try {
        const likesElement = await comment.$('#vote-count-middle');
        if (likesElement) {
          likes = await likesElement.textContent();
        }
      } catch (e) {
        likes = '0';
      }

      if (commentText && author) {
        comments.push({
          author: author.trim(),
          text: commentText.trim(),
          likes: likes.trim()
        });
      }
