  } catch (e) {
    hasSubtitles = false;
  }

  // Get video metadata
  const metadata = {
    title: title.replace(' - YouTube', ''),
    description: description,
    stats: stats,
    channel: channelInfo,
    hasSubtitles: hasSubtitles,
    comments: comments,
    url: page.url()
  };

  return metadata;
}"}

